INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(43778, 0, 0, 'Foe Reaper 5000 on-line.  All systems nominal.', 14, 0, 100.0, 0, 0, 22137, 0, 0, 'Foe Reaper 5000'),
(43778, 1, 0, '|TInterface\\Icons\\ability_whirlwind.blp:20|t Foe Reaper 5000 begins to activate |cFFFF0000|Hspell:88481|h[Overdrive]|h|r!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Foe Reaper 5000'),
(43778, 2, 0, 'Overdrive engine activated.', 14, 0, 100.0, 0, 0, 22142, 0, 0, 'Foe Reaper 5000'),
(43778, 3, 0, 'Acquiring target...', 14, 0, 100.0, 0, 0, 22140, 0, 0, 'Foe Reaper 5000 to Player'),
(43778, 4, 0, 'Target acquired.  Harvesting servos engaged.', 14, 0, 100.0, 0, 0, 22141, 0, 0, 'Foe Reaper 5000'),
(43778, 5, 0, 'Safety restrictions off-line.  Catastrophic system failure imminent.', 14, 0, 100.0, 0, 0, 22143, 0, 0, 'Foe Reaper 5000'),
(43778, 6, 0, '|TInterfaceIconsspell_fire_totemofwrath.blp:20|t Foe Reaper 5000 |cFFFF0000|Hspell:88522|h[Safety Restrictions are Off-line]|h|r!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Foe Reaper 5000'),
(43778, 7, 0, 'Target destroyed.', 14, 0, 100.0, 0, 0, 22139, 0, 0, 'Feindschnitter 5000 to Player'),
(43778, 8, 0, 'Overheat threshold exceeded.  System failure.  Wheat clog in port two.  Shutting down.', 14, 0, 100.0, 0, 0, 22138, 0, 0, 'Foe Reaper 5000'),
(47162, 0, 0, 'Glubtok show you da power of de arcane!', 14, 0, 100.0, 0, 0, 21151, 0, 0, 'Glubtok to Player'),
(47162, 1, 0, 'Fists of flame!', 14, 0, 100.0, 0, 0, 21153, 0, 0, 'Glubtok'),
(47162, 2, 0, 'Fists of frost!', 14, 0, 100.0, 0, 0, 21156, 0, 0, 'Glubtok'),
(47162, 3, 0, 'Glubtok ready?', 14, 0, 100.0, 1, 0, 21154, 0, 0, 'Glubtok'),
(47162, 4, 0, 'Let\'s do it!', 14, 0, 100.0, 15, 0, 21157, 0, 0, 'Glubtok'),
(47162, 5, 0, 'ARCANE POWER!!!', 14, 0, 100.0, 15, 0, 21146, 0, 0, 'Glubtok'),
(47162, 6, 0, '|TInterface\\Icons\\spell_holy_innerfire.blp:20|t Glubtok creates a moving |cFFFF0000|Hspell:91398|h[Fire Wall]|h|r!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Glubtok'),
(47162, 7, 0, 'TOO...MUCH...POWER!!!', 14, 0, 100.0, 15, 0, 21145, 0, 0, 'Glubtok'),
(47296, 0, 0, 'The mistress will pay me handsomely for your heads!', 14, 0, 100.0, 0, 0, 20849, 0, 0, 'Helix Gearbreaker - Aggro'),
(47296, 1, 0, 'Bombs away!', 14, 0, 100.0, 0, 0, 20847, 0, 0, 'Helix Gearbreaker - Bomb'),
(47296, 2, 0, 'Ready Oafie? Throw!', 14, 0, 100.0, 0, 0, 20848, 0, 0, 'Helix Gearbreaker - Throw Helix'),
(47296, 3, 0, 'Helix attaches a bomb to $n\'s chest!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Helix Gearbreaker - Announce Bomb'),
(47296, 4, 0, 'I didn\'t need him! Not when I\'ve got YOU oafs!', 14, 0, 100.0, 0, 0, 20846, 0, 0, 'Helix Gearbreaker - Oaf Death'),
(47296, 5, 0, 'Only ten copper? You\'re not even worth killing!', 14, 0, 100.0, 0, 0, 20845, 0, 0, 'Helix Gearbreaker - Slay'),
(47296, 6, 0, 'The scales...have...tipped...', 14, 0, 100.0, 0, 0, 20844, 0, 0, 'Helix Gearbreaker - Death'),
(47297, 0, 1, 'No...NO!', 14, 0, 100.0, 0, 0, 20854, 0, 0, 'Lumbering Oaf to Helix Gearbreaker'),
(47297, 1, 2, 'OAF SMASH!!', 14, 0, 100.0, 0, 0, 0, 0, 0, 'Lumbering Oaf to Helix Gearbreaker'),
(47626, 0, 0, 'Ah, fresh meat!', 14, 0, 100.0, 0, 0, 19882, 0, 0, 'Admiral Ripsnarl - Aggro'),
(47626, 1, 0, 'Do you feel that chill running up your spine?', 14, 0, 100.0, 0, 0, 19877, 0, 0, 'Admiral Ripsnarl - Fog 1'),
(47626, 2, 0, 'The fog is rolling in...', 14, 0, 100.0, 0, 0, 0, 0, 0, 'Admiral Ripsnarl - Fog 2'),
(47626, 3, 0, 'Your blood only increases my hunger!', 14, 0, 100.0, 0, 0, 19876, 0, 0, 'Admiral Ripsnarl - Slay'),
(47626, 4, 0, 'I can smell your fear...', 14, 0, 100.0, 0, 0, 19879, 0, 0, 'Admiral Ripsnarl - Go for the Throat 1'),
(47626, 4, 1, 'I will rip your heart from your chest!', 14, 0, 100.0, 0, 0, 19880, 0, 0, 'Admiral Ripsnarl - Go for the Throat 2'),
(47626, 5, 0, 'Multiple vapors appear from the fog!  Kill Admiral Ripsnarl before you are overwhelmed!', 41, 0, 100.0, 0, 0, 19878, 0, 0, 'Admiral Ripsnarl - Announce Vapor'),
(47626, 6, 0, 'You will...NOT find her...until it is too late...', 14, 0, 100.0, 0, 0, 19875, 0, 0, 'Admiral Ripsnarl - Death'),
(48280, 0, 0, 'They\'re alive...', 12, 0, 100.0, 0, 0, 0, 0, 0, 'Goblin Craftsman to Player'),
(48280, 1, 0, 'THEY\'RE ALIVE!!!', 14, 0, 100.0, 0, 0, 0, 0, 0, 'Goblin Craftsman to Player'),
(48280, 2, 0, 'NOOOOOOO!!!', 14, 0, 100.0, 0, 0, 0, 0, 0, 'Goblin Craftsman to Player'),
(48439, 0, 0, 'RUN!', 14, 0, 100.0, 0, 0, 0, 0, 0, 'Goblin Engineer to Player'),
(49139, 0, 0, 'Blowin\' em\' to bits, boss!', 12, 0, 100.0, 0, 0, 0, 0, 0, 'Helix Crew - Throw Bomb'),
(49429, 0, 0, 'You hear a noise from above the cabin door!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Vanessa van Cleef to Player'),
(49429, 1, 0, 'I\'ve been waiting a long time for this, you know.', 12, 0, 100.0, 1, 0, 24613, 0, 0, 'Vanessa van Cleef to Player'),
(49429, 2, 0, 'Biding my time, building my forces, studying the minds of my enemies.', 12, 0, 100.0, 1, 0, 24614, 0, 0, 'Vanessa van Cleef to Player'),
(49429, 3, 0, 'I was never very good at hand-to-hand combat, you know.  Not like my father.', 12, 0, 100.0, 1, 0, 24615, 0, 0, 'Vanessa van Cleef to Player'),
(49429, 4, 0, 'But I always excelled at poisons.', 12, 0, 100.0, 1, 0, 24616, 0, 0, 'Vanessa van Cleef to Player'),
(49429, 5, 0, 'Especially venoms that affect the mind.', 12, 0, 100.0, 1, 0, 24617, 0, 0, 'Vanessa van Cleef to Player'),
(49429, 6, 0, 'Vanessa injects you with the Nightmare Elixir!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Vanessa van Cleef to Player'),
(49454, 0, 0, 'Activate the steam valves to free yourself!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Vanessa\'s Trap Bunny to Player'),
(49536, 0, 0, 'James...please...I love you...', 12, 0, 100.0, 0, 0, 0, 0, 3, 'Calissa Harrington'),
(49536, 1, 0, 'Calissa is dying!', 41, 0, 100.0, 0, 0, 0, 0, 3, 'Calissa Harrington'),
(49539, 0, 0, 'Calissa...I am so sorry...', 12, 0, 100.0, 0, 0, 0, 0, 3, 'James Harrington'),
(49541, 0, 0, 'I will not share my father\'s fate!  Your tale ends here!', 14, 0, 100.0, 0, 0, 24599, 0, 0, 'Vanessa van Cleef to Player'),
(49541, 1, 0, 'The first of many.', 14, 0, 100.0, 0, 0, 24620, 0, 0, 'Vanessa van Cleef'),
(49541, 2, 0, 'Did you really think I would come to this fight alone?', 14, 0, 100.0, 0, 0, 24620, 0, 0, 'Vanessa van Cleef'),
(49541, 3, 0, 'Fools!  This entire ship is rigged with explosives!  Enjoy your fiery deaths!', 14, 0, 100.0, 0, 0, 24621, 0, 0, 'Vanessa van Cleef'),
(49541, 4, 0, 'Vanessa has detonated charges on the ship!  Get to the ropes at the side of the boat!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Vanessa van Cleef'),
(49541, 5, 0, 'You didn\'t honestly think I would only plant ONE set of explosives, did you?', 14, 0, 100.0, 0, 0, 24622, 0, 0, 'Vanessa van Cleef'),
(49541, 6, 0, 'Vanessa is detonating more charges!  Get to the ropes at the side of the boat!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Vanessa van Cleef'),
(49541, 7, 0, 'ENOUGH!  I will not give you the pleasure!', 14, 0, 100.0, 274, 0, 24610, 0, 0, 'Vanessa van Cleef'),
(49541, 8, 0, 'If I\'m going to die, I\'m taking you all with me!', 14, 0, 100.0, 15, 0, 24611, 0, 0, 'Vanessa van Cleef'),
(49541, 9, 0, 'Vanessa pulls out a final barrel of mining powder and ignites it!  RUN!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Vanessa van Cleef'),
(49541, 10, 0, 'MY FATE IS MY OWN!', 14, 0, 100.0, 397, 0, 24612, 0, 0, 'Vanessa van Cleef'),
(49564, 0, 0, 'A note falls to the floor!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'A Note from Vanessa to Player'),
(49671, 0, 0, 'Poor Glubtok.  When his powers manifested, his own ogre mound was the first to burn.', 12, 0, 100.0, 1, 0, 24602, 0, 0, 'Vanessa van Cleef to Steam Valve'),
(49671, 1, 0, 'Deep within his soul, the one thing he feared most of all was...himself.', 12, 0, 100.0, 1, 0, 24603, 0, 0, 'Vanessa van Cleef to Steam Valve'),
(49671, 2, 0, 'You have entered Glubtok\'s Nightmare!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Vanessa van Cleef to Steam Valve'),
(49671, 3, 0, 'Get back to the ship!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Vanessa van Cleef to Steam Valve'),
(49671, 4, 0, 'Most rogues prefer to cloak themselves in the shadows, but not Helix.', 12, 0, 100.0, 1, 0, 24604, 0, 0, 'Vanessa van Cleef to Player'),
(49671, 5, 0, 'You never know what skitters in the darkness.', 12, 0, 100.0, 1, 0, 24605, 0, 0, 'Vanessa van Cleef to Player'),
(49671, 6, 0, 'Can you imagine the life of a machine?', 12, 0, 100.0, 1, 0, 24606, 0, 0, 'Vanessa van Cleef to Player'),
(49671, 7, 0, 'A simple spark can mean the difference between life...and death.', 12, 0, 100.0, 1, 0, 24607, 0, 0, 'Vanessa van Cleef to Player'),
(49671, 8, 0, 'You have entered the mechanical nightmare!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Vanessa van Cleef to Player'),
(49671, 9, 0, 'Ripsnarl wasn\'t always a bloodthirsty savage.  Once, he even had a family.', 12, 0, 100.0, 1, 0, 24608, 0, 0, 'Vanessa van Cleef to Player'),
(49671, 10, 0, 'He was called James Harrington.  A tragedy in three parts.', 12, 0, 100.0, 1, 0, 24609, 0, 0, 'Vanessa van Cleef to Player'),
(49671, 11, 0, 'You have entered Ripsnarl\'s nightmare!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Vanessa van Cleef to Player'),
(49674, 0, 0, 'You have entered Helix\'s nightmare!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Helix Gearbreaker to Player'),
(49674, 1, 0, 'Nightmare spiders appear in the darkness!  Kill Helix before his nightmare overwhelms you!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Helix Geabreaker to Player');
